mapper.select:
select 
from dm_sys_attachment
where attachment_type = #{attachmentType}
  and attachment_status = 'EDITING'
  and file_name = #{fileName}

select 
from dm_sys_attachment
where attachment_status = 'EDITING'
  and  gmt_modified <= #{before} 
order by gmt_modified
limit #{limit}

mapper.delete:
delete from dm_sys_attachment
where id = #{id}
  and attachment_status = 'EDITING'
  and  gmt_modified <= #{before}

mapper.update:
update dm_sys_attachment
set gmt_modified = now()
where id = #{id}
  and owner_uid = #{ownerUid}
  and attachment_status = 'EDITING'
  and  gmt_modified > #{before}

update dm_sys_attachment
set approval_id = #{approvalId},
    attachment_status = 'CONFIRMED',
    gmt_modified = now()
where id = #{id}
  and owner_uid = #{ownerUid}
  and attachment_status = 'EDITING'
  and  gmt_modified > #{before}
